38	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
39	pub enum ManaSymbol {
40	    /// A colored mana symbol: {W}, {U}, {B}, {R}, {G}
41	    Colored(Color),
42	    /// Generic mana: {1}, {2}, etc. Can be paid with any type.
43	    Generic(u32),
44	    /// Specifically colorless mana: {C}
45	    Colorless(u32),
46	    /// Variable cost
