308	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
309	pub enum CreatureFilter {
310	    /// All creatures you control.
311	    You,
312	    /// All creatures opponents control.
313	    Opponents,
314	    /// Token creatures you control.
315	    YourTokens,
316	    /// Creatures matching a subtype (e.g., "Human", "Zombie").
317	    HasSubtype(String),
