332	pub enum EffectScope {
333	    /// Affects only the permanent this effect is on (static keyword on a creature).
334	    OnSelf,
335	    /// Affects the creature this aura/equipment is attached to.
336	    Attached,
337	    /// Affects all creatures matching a filter, INCLUDING the source permanent.
338	    /// Used for "Creatures you control get +1/+1" (Glorious Anthem).
339	    Global(CreatureFilter),
340	    /// Affects all creatures matching a filter, EXCLUDING the source permanent.
341	    /// Used for "Other Spirit creatures you control get +1/+0" (lords).
342	    GlobalOther(CreatureFilter),
343	}
