192	            took_action = true;
193	        }
194	
195	        // Rule 704.5q: +1/+1 and -1/-1 counters annihilate in pairs.
196	        let counter_targets: Vec<_> = state.objects.values()
197	            .filter(|o| {
198	                o.zone == Zone::Battlefield
199	                    && *o.counters.get(&crate::types::CounterType::PlusOnePlusOne).unwrap_or(&0) > 0
